{
  "recipes": [
    {
      "title": "LE SOUFFLÉ AU FROMAGE LA VERSION TRADI",
      "type": "dessert",
      "servings": 3,
      "ingredients": [
        {
          "raw": "beurre pour moule à soufflé de 16 cm de diamètre",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "4 œufs",
          "quantity": 4,
          "unit": null,
          "label": null
        },
        {
          "raw": "2 pincées de sel",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "25 cl de lait",
          "quantity": 25,
          "unit": "cl",
          "label": null
        },
        {
          "raw": "40 g de beurre",
          "quantity": 40,
          "unit": "g",
          "label": null
        },
        {
          "raw": "40 g de farine",
          "quantity": 40,
          "unit": "g",
          "label": null
        },
        {
          "raw": "100 g de comté finement râpé",
          "quantity": 100,
          "unit": "g",
          "label": "finement râpé"
        },
        {
          "raw": "1 c. à soupe de crème épaisse",
          "quantity": 1,
          "unit": null,
          "label": "à soupe de crème épaisse"
        },
        {
          "raw": "sel, poivre et noix muscade",
          "quantity": null,
          "unit": null,
          "label": null
        }
      ],
      "steps": [
        "Préchauffez le four à 180 °C. Séparer les blancs des jaunes. Mettez les blancs dans un saladier, ajoutez 2 pincées de sel.",
        "Faites fondre 40 g de beurre dans une casserole, ajoutez 40 g de farine et mélangez 1 mn sur feu doux.",
        "Versez le lait bouillant en filet, sans cesser de remuer, et laissez épaissir sur feu doux, en tournant sans cesse 5 mn, jusqu’à obtenir une crème épaisse. Retirez du feu.",
        "Ajoutez 1 c. à soupe de crème épaisse, sel, poivre et noix muscade.",
        "Battez les blancs d’œufs en neige pas trop ferme puis ajoutez-en 1/4 dans la crème. Mélangez vivement au fouet puis versez ce mélange dans le reste des blancs.",
        "Incorporez 100 g de comté finement râpé. Versez la préparation dans le moule qu’elle doit remplir aux 3/4.",
        "Glissez au four et laissez cuire 30 mn, jusqu’à ce que le soufflé soit gonflé et doré. Servez aussitôt."
      ]
    },
    {
      "title": "LA VERSION LIGHT DE DAVID ZUDDAS",
      "type": "dessert",
      "servings": 8,
      "ingredients": [
        {
          "raw": "300 g de pommes de terre",
          "quantity": 300,
          "unit": "g",
          "label": "de pommes de terre"
        },
        {
          "raw": "25 cl de lait chaud",
          "quantity": 25,
          "unit": "cl",
          "label": "chaud"
        },
        {
          "raw": "120 g de comté râpé fin",
          "quantity": 120,
          "unit": "g",
          "label": "râpé fin"
        },
        {
          "raw": "6 jaunes d’œufs",
          "quantity": 6,
          "unit": null,
          "label": "jaunes d’œufs"
        },
        {
          "raw": "8 blancs en neige",
          "quantity": 8,
          "unit": null,
          "label": "en neige"
        }
      ],
      "steps": [
        "Faites cuire 300 g de pommes de terre à la vapeur puis réduisez-les en fine purée au moulin à légumes.",
        "Incorporez 25 cl de lait chaud et 120 g de comté râpé fin. Ajoutez 6 jaunes d’œufs, délicatement.",
        "Préchauffez le four à 170 °C.",
        "Chemisez 8 cercles de papier sulfurisé, en le faisant dépasser. Versez la préparation et glissez 15 mn au four.",
        "Lorsque les soufflés sont cuits, dressez-les dans des assiettes et retirez le cercle et le papier. Servez aussitôt, accompagné de mesclun et de tranches de magret fumé."
      ]
    }
  ]
}
